<?php	include("../config.inc.php");	require( "../lib/dhabiles.inc.php" );	Encabezado();	$datos = Verifica_Sesion();	$Nombre_Usuario = usr_datos($datos["IDUsuario"]);	$ID_Usuario = $datos["IDUsuario"];	$Nivel =  $datos["Nivel"];	$IVA = $datos["IVA"];	$sep = "\t";	$cal = new Date_Calc();		$ReteICA =  get_field( "ReteICA","Valor","IDReteICA",1 )  ;	$ReteIVA = get_field( "ReteIVA","Valor","IDReteIVA",1 ) / 100;	$ReteFuente = get_field( "ReteFuente","Valor","IDReteFuente",1 ) / 100;		//traer las fechas del rago seleccionado	$array_fechas = dhabiles($FechaDesde, $FechaHasta);		//traer los codigo de bancos	$qry_bancos = db_query( $sql_bancos = "SELECT IDBanco, Codigo FROM Banco");	while( $r_bancos = db_fetch_array( $qry_bancos ) )	{		$array_bancos[$r_bancos[IDBanco]] = $r_bancos[Codigo];	}//en while bancos			$sql_facturas = " SELECT F.*, 						DATE_FORMAT( F.FechaFactura,'%Y-%m-%e' ) as FechaFacturaF,						SUM( F.ValorTotal ) as TotalFactura, SUM( FP.Valor ) as ValorFP,FP.*,						SUM( ( FP.Valor * ( 1 - $IVA ) ) * ( FP.Comision / 100 ) ) as ComisionFP						FROM Factura F, FormaPagoFactura FP						WHERE F.IDPuntoVenta = '$IDPuntoVenta' 						AND F.FechaFactura BETWEEN '$FechaDesde' AND '$FechaHasta' 						AND F.IDFactura = FP.IDFactura						AND FP.IDFormaPago > 2						GROUP BY FP.IDFormaPago, DATE_FORMAT( F.FechaFactura, '%Y-%c-%e' )						ORDER BY FechaFactura ASC";								$qry_facturas = db_query( $sql_facturas );		$i = 0;	$formapago = array();		while( $r_facturas = db_fetch_array( $qry_facturas ) )	{		$array_factura[$r_facturas['FechaFacturaF']][$i] = $r_facturas;		$i++;	}//end while( $r_facturas = db_fetch_array( $qry_facturas ) )	//print_r( $r_facturas );			 /********************* TRAER DATOS DE VENTAS CON EFECTIVO 'ID'S MENOR O IGUAL QUE 2'*********************/	 $sql_facturasef = " SELECT F.*, 							DATE_FORMAT( F.FechaFactura,'%Y-%m-%e' ) as FechaFacturaF,							SUM( F.ValorTotal ) as TotalFactura, SUM( FP.Valor ) as ValorFP,FP.*							FROM Factura F, FormaPagoFactura FP							WHERE F.IDPuntoVenta = '$IDPuntoVenta' 							AND F.FechaFactura BETWEEN '$FechaDesde' AND '$FechaHasta' 							AND F.IDFactura = FP.IDFactura							AND FP.IDFormaPago <= 2							GROUP BY  DATE_FORMAT( F.FechaFactura, '%Y-%c-%e' )							ORDER BY FechaFactura ASC";								$qry_facturasef = db_query( $sql_facturasef );		$i = 0;	$formapagoef = array();		while( $r_facturasef = db_fetch_array( $qry_facturasef ) )	{		$array_facturaef[$r_facturasef['FechaFacturaF']][$i] = $r_facturasef;		$i++;	}//end while( $r_facturasef = db_fetch_array( $qry_facturasef ) )			foreach( $array_fechas as $Fecha => $valor )  //foreach de las fechas del rango seleccionado	{ 		$class = repetition()?"row2":"row1";		//print_r($valor);		foreach( $array_factura as $key => $datos ) //formeach de la consulta realizada para traer los dros		{			foreach( $datos as $llave => $dato ) //foreach de los datos de la consulta ( array anidado de la consulta )			{				if( in_array( $key, $valor ) ) //si la fecha de venta esta dentro del array de las fechas que hay que consignar				{					$Base = $dato['ValorFP'] * ( 1 - $IVA );					$ValorIVA = $dato['ValorFP'] *  $IVA ;							$ValorTotal = $dato['ValorFP'];					$Comision = $dato['ComisionFP'];					$ValorRetefuente = ( $Base * $ReteFuente ); 					$Neto = $ValorTotal - $Comision;					$ValorRIVA = $ValorIVA * $ReteIVA; 					$ValorRICA = ( ($Base / 1000) * $ReteICA );					$Ingreso = ( $Neto - $ValorRetefuente -  $ValorRIVA - $ValorRICA );					$CBanco = $array_bancos[$dato[IDBanco]];										$array_valores[$Fecha][$dato['IDFormaPago']]['IDBanco'] =  $CBanco;					$array_valores[$Fecha][$dato['IDFormaPago']]['Venta'] +=  $ValorTotal;					$array_valores[$Fecha][$dato['IDFormaPago']]['Comision'] +=  $Comision;					$array_valores[$Fecha][$dato['IDFormaPago']]['ValorRetefuente'] +=  $ValorRetefuente;					$array_valores[$Fecha][$dato['IDFormaPago']]['Neto'] +=  $Neto;					$array_valores[$Fecha][$dato['IDFormaPago']]['ValorRIVA'] +=  $ValorRIVA;					$array_valores[$Fecha][$dato['IDFormaPago']]['ValorRICA'] +=  $ValorRICA;					$array_valores[$Fecha][$dato['IDFormaPago']]['Ingreso'] +=  $Ingreso;				}//end if			}//end forech		}//end foreach	}//end foreach( $r_facturas as $key => $valor )				foreach( $array_valores as $Fecha => $valor )	{		foreach( $valor as $FormaPago => $datos )		{			//formatear fecha ( AAAAMMDD )						$ano = substr( $Fecha, 0,4 );			$mes = substr( $Fecha, 5,2 );			$dia = substr( $Fecha, 8,2 );			$Fecha = $cal->dateFormat( $dia, $mes, $ano,"%Y%m%d" );						$row =  "00".$sep;				$row .= $Fecha.$datos[IDBanco].$sep;			$row .= $datos[Venta].$sep;			$row .= $datos[Comision].$sep;			$row .= $datos[ValorRetefuente].$sep;			$row .= $datos[Neto].$sep;			$row .= $datos[ValorRIVA].$sep;			$row .= $datos[ValorRICA].$sep;			$row .= $datos[Ingreso].$sep;						$strfile .= $row."\n";						}//end for	}//end for			/************************* MOSTRAR LAS VENTAS CON EFECTIVO ********************************/	foreach( $array_fechas as $Fecha => $valor )	{ 		$class = repetition()?"row2":"row1";		//print_r($valor);		foreach( $array_facturaef as $key => $datos )		{			foreach( $datos as $llave => $dato )			{				if( in_array( $key, $valor ) )				{					$Base = $dato['ValorFP'] * ( 1 - $IVA );					$ValorIVA = $dato['ValorFP'] *  $IVA ;							$ValorTotal = $dato['ValorFP'];					$Comision = 0;					$ValorRetefuente = 0;//( $Base * $ReteFuente ); 					$Neto = $ValorTotal - $Comision;					$ValorRIVA = 0;//$ValorIVA * $ReteIVA; 					$ValorRICA = 0;//( ($Base / 1000) * $ReteICA );					$Ingreso = ( $Neto - $ValorRetefuente -  $ValorRIVA - $ValorRICA );					$CBanco = $array_bancos[$dato[IDBanco]];										$array_valoresef[$Fecha]['IDBanco'] =  $CBanco;					$array_valoresef[$Fecha]['Venta'] +=  $ValorTotal;					$array_valoresef[$Fecha]['Comision'] +=  $Comision;					$array_valoresef[$Fecha]['ValorRetefuente'] +=  $ValorRetefuente;					$array_valoresef[$Fecha]['Neto'] +=  $Neto;					$array_valoresef[$Fecha]['ValorRIVA'] +=  $ValorRIVA;					$array_valoresef[$Fecha]['ValorRICA'] +=  $ValorRICA;					$array_valoresef[$Fecha]['Ingreso'] +=  $Ingreso;				}//end if			}//end forech		}//end foreach	}//end foreach( $r_facturas as $key => $valor )	foreach( $array_valoresef as $Fecha => $datos )	{					$ano = substr( $Fecha, 0,4 );		$mes = substr( $Fecha, 5,2 );		$dia = substr( $Fecha, 8,2 );		$Fecha = $cal->dateFormat( $dia, $mes, $ano,"%Y%m%d" );				$row  =  "00".$sep;			$row .= $Fecha.$datos[IDBanco].$sep;		$row .= $datos[Venta].$sep;		$row .= $datos[Comision].$sep;		$row .= $datos[ValorRetefuente].$sep;		$row .= $datos[Neto].$sep;		$row .= $datos[ValorRIVA].$sep;		$row .= $datos[ValorRICA].$sep;		$row .= $datos[Ingreso].$sep;				$strfile .= $row."\n";	}//end for		/********************** FIN DE MOSTRAR LAS FECHAS CON EFECTIVO *********************************************/		$file_type = "text/plain";	$file_ending = "txt";	$archivo = "Mensual ".$FechaDesde." - ".$FechaHasta." - ".get_field( "PuntoVenta","Nombre","IDPuntoVenta",$IDPuntoVenta );		header("Content-Type: application/$file_type");	header("Content-Disposition: attachment; filename=$archivo.$file_ending");	header("Pragma: no-cache");	header("Expires: 0");	echo $strfile;?>